# Surah Al-Baqarah (chapter 2) — part 11: ayat 101-110 (IDs 108-117)
SURAH = 2

ENTRIES = {
108: (
"اور جب ان کے پاس اللہ کی طرف سے کوئی رسول آئے جو تصدیق کرتا ہے اس چیز کی جو ان کے پاس (موجود) ہے تو اہل کتاب میں سے ایک گروہ نے اللہ کی کتاب کو اپنی پیٹھوں کے پیچھے پھینک دیا گویا وہ جانتے ہی نہیں۔",
"""۱۔ اہل کتاب کا طرز عمل — جب قرآن انکے پاس آیا جو ان کی موجودہ کتاب کی تصدیق کرتا تھا — تب بھی انہوں نے اسے قبول نہ کیا۔
۲۔ ’’نَبَذَ فَرِيقٌ مِّنَ الَّذِينَ أُوتُوا الْكِتَابَ كِتَابَ اللّٰہِ وَرَاءَ ظُهُورِهِمْ‘‘ — ان میں سے ایک گروہ نے اللہ کی کتاب کو اپنی پیٹھوں کے پیچھے پھینک دیا۔ یعنی جان بوجھ کر بدتمیزی اور اعراض۔
۳۔ ’’كَأَنَّهُمْ لَا يَعْلَمُونَ‘‘ — گویا وہ جانتے ہی نہیں۔ یعنی علم کے باوجود انکار — یہ سب سے بدتر قسم کا انکار ہے۔
۴۔ عملی سبق: اللہ کی کتاب کو تسلیم کرنے میں تاخیر نہ کریں؛ جانتے ہوئے اعراض سب سے بڑا زیاں ہے۔"""
),
109: (
"اور وہ اُس چیز کی پیروی کرتے ہیں جو شیاطین سلیمان کی بادشاہت کے بارے میں پڑھتے تھے — اور سلیمان نے کفر نہیں کیا مگر شیاطین کفر کرتے — وہ لوگوں کو سحر سکھاتے اور وہ چیز جو بابل میں دو فرشتوں ہاروت اور ماروت پر نازل کی گئی — اور وہ دونوں کسی کو بھی نہیں سکھاتے تھے یہاں تک کہ (پہلے) کہہ دیتے: ہم تو ایک آزمائش ہیں، لہٰذا کافر نہ ہو (جادو سیکھ کر) — پھر بھی وہ ان دونوں سے وہ سیکھتے تھے جس کے ذریعے وہ مرد اور اس کی بیوی کے درمیان جدائی ڈالتے — حالانکہ وہ اس (سحر) سے کسی کو بھی نقصان نہیں پہنچا سکتے مگر اللہ کے حکم سے — اور وہ وہ سیکھتے تھے جو انہیں نقصان دیتا اور فائدہ نہ دیتا — اور وہ ضرور جانتے تھے کہ جس نے اس (سحر) کو خریدا (سیکھ کر) اس کے لیے آخرت میں کوئی حصہ نہیں — اور وہ بہت بُری چیز ہے جس کے بدلے انہوں نے خود کو بیچا — کاش وہ جانتے۔",
"""۱۔ اہل کتاب کا ایک اور طرز عمل: انہوں نے قرآن کے بجائے جادو اور سحر سیکھنے کو اختیار کیا — جو سلیمان علیہ السلام کی حکومت کے زمانے سے چل رہا تھا۔
۲۔ ’’وَمَا كَفَرَ سُلَيْمَانُ وَلَٰكِنَّ الشَّيَاطِينَ كَفَرُوا‘‘ — اور سلیمان نے کفر نہیں کیا بلکہ شیاطین ہی کفر کرتے تھے — یعنی سلیمان علیہ السلام کو شیاطین کی حرکتوں سے کوئی تعلق نہیں؛ انہوں نے ہر گز شرک یا کفر نہیں کیا۔
۳۔ ’’يُعَلِّمُونَ النَّاسَ السِّحْرَ‘‘ — وہ لوگوں کو سحر سکھاتے تھے — یعنی سحر کی تعلیم شیاطین کی طرف سے انسانوں میں پھیلی۔
۴۔ ’’وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ‘‘ — اور وہ چیز جو بابل میں دو فرشتوں ہاروت اور ماروت پر نازل کی گئی — اللہ نے ان دونوں کو آزمائش کے طور پر سحر سکھانے کے لیے بھیجا تھا۔
۵۔ ’’وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ‘‘ — اور وہ دونوں کسی کو بھی نہیں سکھاتے تھے یہاں تک کہ پہلے کہہ دیتے: ہم تو آزمائش (فتنہ) ہیں، لہٰذا کافر نہ ہو — یعنی ان کی تعلیم چھپی ہوئی بات نہیں بلکہ کھلی تنبیہ کے ساتھ تھی۔
۶۔ ’’فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ‘‘ — پھر بھی وہ ان دونوں سے وہ سیکھتے تھے جس کے ذریعے وہ مرد اور اس کی بیوی کے درمیان جدائی ڈالتے — یعنی سحر کا سب سے خطرناک استعمال گھروں کو تباہ کرنا تھا۔
۷۔ ’’وَمَا هُم بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللّٰہِ‘‘ — حالانکہ وہ اس سے کسی کو بھی نقصان نہیں پہنچا سکتے مگر اللہ کے حکم سے — یعنی سحر کی قوت بھی اللہ کی مشیت کے بغیر کچھ نہیں کرتی۔
۸۔ ’’وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ‘‘ — اور وہ وہ سیکھتے تھے جو انہیں نقصان دیتا اور فائدہ نہ دیتا — یعنی خالص خسارے کا سودا۔
۹۔ ’’وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ‘‘ — اور وہ ضرور جانتے تھے کہ جس نے اسے خریدا (سیکھ کر) اس کے لیے آخرت میں کوئی حصہ نہیں — یعنی انہیں خود معلوم تھا کہ سحر کی تعلیم سے آخرت میں نجات نہیں ملتی۔
۱۰۔ عملی سبق: سحر، جادو اور ٹونے کا علم حاصل نہ کریں؛ یہ دین کے سخت ناجائز کاموں میں سے ہے — حتیٰ کہ آزمائش کے طور پر بھی اسے تسلیم نہ کریں۔"""
),
110: (
"اور اگر وہ ایمان لاتے اور ڈڑتے تو (ان کے لیے) اللہ کی طرف سے بہترین اجر (ثواب) ہوتا — کاش وہ جانتے۔",
"""۱۔ اللہ نے واضح کر دیا کہ اہل کتاب کا خسارہ ان کی اپنی روش کا نتیجہ ہے — ورنہ متبادل خوش بختی ممکن تھی۔
۲۔ ’’آمَنُوا وَاتَّقَوْا‘‘ — ایمان لاتے اور تقویٰ اختیار کرتے — ایمان اور تقویٰ دونوں شرط ہیں۔
۳۔ ’’لَمَثُوبَةٌ مِّنْ عِندِ اللّٰہِ خَيْرٌ‘‘ — تو اللہ کی طرف سے بہترین ثواب ملتا — یعنی سحر اور دنیاوی مفاد کے مقابلے میں اللہ کا اجر بہت بہتر ہے۔
۴۔ عملی سبق: نقصان دہ چیز چھوڑ کر فائدہ مند چیز اختیار کرو؛ اللہ کا اجر ہر چیز سے بہتر ہے۔"""
),
111: (
"اے ایمان والو! نہ کہا کرو (پیغمبر سے) ’’رَاعِنَا‘‘ (ہم رعایت چاہیں گے) بلکہ کہو ’’انظُرْنَا‘‘ (ہماری طرف دیکھئے) — اور (اچھی طرح) سنو — اور کافروں کے لیے دردناک عذاب ہے۔",
"""۱۔ مؤمنوں کو ادب سکھایا جا رہا ہے کہ رسول اللہ ﷺ سے بات کرتے وقت الفاظ کا انتخاب بہت محتاط ہو۔
۲۔ ’’لَا تَقُولُوا رَاعِنَا وَقُولُوا انظُرْنَا‘‘ — ’’رَاعِنَا‘‘ مت کہو، ’’انظُرْنَا‘‘ کہو — کیونکہ ’’رَاعِنَا‘‘ ایک ایسا لفظ ہے جو اہل مدینہ کے ہاں بے ادبی کا معنی بھی رکھتا تھا (بے وقوف سمجھنے کا) — جبکہ ’’انظُرْنَا‘‘ کا مطلب ہے ’’ہماری طرف توجہ دیجیے‘‘۔
۳۔ ’’وَاسْمَعُوا‘‘ — اور (کان لگا کر) سنو — یعنی وحی کی بات بڑے ادب اور دھیان سے سنو۔
۴۔ ’’وَلِلْكَافِرِينَ عَذَابٌ أَلِيمٌ‘‘ — اور کافروں کے لیے دردناک عذاب ہے — یعنی رسول کی بے ادبی میں کفر شامل ہو سکتا ہے۔
۵۔ عملی سبق: نبی ﷺ کی سیرت کا احترام ہر مسلمان پر لازم ہے — الفاظ کا ادب، توجہ کے ساتھ سننا اور بے ادبی سے بچنا۔"""
),
112: (
"جو لوگ کافر ہیں اہل کتاب میں سے اور مشرکین — وہ نہیں چاہتے کہ تم پر تمہارے رب کی طرف سے کوئی خیر نازل ہو — اور اللہ اپنی رحمت جسے چاہے دیتا ہے — اور اللہ بڑے فضل والا ہے۔",
"""۱۔ سعادت کا یہ بنیادی اصول سامنے رکھا جا رہا ہے: اہل کتاب اور مشرکین دونوں نہیں چاہتے کہ تم پر کوئی خیر نازل ہو۔
۲۔ ’’لَا يَوَدُّ الَّذِينَ كَفَرُوا… أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ‘‘ — کافر (اہل کتاب اور مشرکین) اس بات کے خواہشمند نہیں کہ تم پر تمہارے رب کی طرف سے کوئی خیر نازل ہو — یعنی رشک اور حسد کا طرز عمل۔
۳۔ ’’وَاللّٰہُ يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ‘‘ — اور اللہ اپنی رحمت جسے چاہے خاص کرتا ہے — یعنی نبوت و ہدایت اللہ کا انتخاب ہے، کوئی اسے روک نہیں سکتا۔
۴۔ ’’وَاللّٰہُ ذُو الْفَضْلِ الْعَظِيمِ‘‘ — اور اللہ بڑے فضل والا ہے — یعنی اس کا فضل ہر چیز پر غالب ہے۔
۵۔ عملی سبق: دشمنوں کے حسد کے سامنے اللہ کے فضل کا بھروسا رکھیں؛ خیر اللہ دے گا، کوئی اسے روک نہیں سکتا۔"""
),
113: (
"ہم کسی آیت (حکم/پڑھی جانے والی بات) کو منسوخ کریں یا بھلا دیں — تو اس سے بہتر یا اُس جیسی (کوئی اور آیت) لے آتے ہیں — کیا تمہیں معلوم نہیں کہ اللہ ہر چیز پر قادر ہے؟",
"""۱۔ قرآن میں بعض مقامات پر سابق حکم کو نئے حکم سے تبدیل کیا گیا ہے — اسی عمل کو ’’نَسْخ‘‘ (منسوخی) کہتے ہیں۔
۲۔ ’’مَا نَنسَخْ مِنْ آيَةٍ أَوْ نُنسِهَا‘‘ — ہم کسی آیت (حکم/پڑھی جانے والی بات) کو منسوخ کریں یا بھلا دیں — یعنی ایک حکم کی جگہ دوسرا حکم دے دیں یا اس کی تلاوت اٹھا لیں۔
۳۔ ’’نَأْتِ بِخَيْرٍ مِّنْهَا أَوْ مِثْلِهَا‘‘ — تو اس سے بہتر یا اُس جیسی (کوئی اور آیت) لے آتے ہیں — یعنی نئے حکم میں بھی خیر اور فائدہ ہوتا ہے؛ منسوخی کیفیت میں کوئی نقص نہیں۔
۴۔ ’’أَلَمْ تَعْلَمْ أَنَّ اللّٰہَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — کیا تمہیں معلوم نہیں کہ اللہ ہر چیز پر قادر ہے — یعنی اس کا حاکمیت و حکمت مطلق ہے۔
۵۔ یہاں دلیل کے طور پر حکمت بیان کی گئی: شریعت کا تدریجی ارتقاء انسانی معاشرت کے مطابق تھا — اللہ جانتا ہے کہ کب کیا مناسب ہے۔
۶۔ عملی سبق: قرآن کے احکام کی منسوخی (جیسے بعض سابق احکام میں تبدیلی) کو مشکل محسوس نہ کرو؛ اللہ کی حکمت ہر حال میں سب سے بہتر ہے۔"""
),
114: (
"کیا تمہیں معلوم نہیں کہ اللہ ہی کے لیے ہے آسمانوں اور زمین کی بادشاہت — اور نہیں ہے تمہارے لیے اللہ کے سوا نہ کوئی سرپرست اور نہ کوئی مددگار؟",
"""۱۔ اللہ کی ملکیت اور حاکمیت کا کھلا اعلان: آسمانوں اور زمین کی بادشاہت صرف اسی کی ہے۔
۲۔ ’’مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ‘‘ — آسمانوں اور زمین کی بادشاہت — یعنی پورا کائنات اللہ کے قبضے اور ملکیت میں ہے۔
۳۔ ’’وَمَا لَكُم مِّن دُونِ اللّٰہِ مِن وَلِيٍّ وَلَا نَصِيرٍ‘‘ — اور نہیں ہے تمہارے لیے اللہ کے سوا نہ کوئی سرپرست اور نہ کوئی مددگار — یعنی حقیقی پناہ اور مدد صرف اللہ سے ملتی ہے۔
۴۔ عملی سبق: اپنی مدد اور حمایت کا رنگ ہمیشہ اللہ پر رکھیں؛ مخلوق سہارا نہیں بلکہ واسطہ ہے۔"""
),
115: (
"کیا تم چاہتے ہو کہ اپنے پیغمبر سے سوال کرو جیسا کہ موسیٰ سے سوال پہلے (زمانے میں) کیا گیا؟ — اور جس نے ایمان کو کفر سے بدل لیا (تو) بے شک وہ سیدھے راستے سے بھٹک گیا۔",
"""۱۔ مؤمنوں کو خبردار کیا جا رہا ہے کہ نبی ﷺ سے بلا ضرورت باریک اور ضد والی سوالات نہ کریں — جیسے بنی اسرائیل نے موسیٰ سے ناحق سوالات کیے تھے۔
۲۔ ’’أَمْ تُرِيدُونَ أَن تَسْأَلُوا رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ‘‘ — کیا تم اپنے پیغمبر سے سوال کرنا چاہتے ہو جیسا کہ موسیٰ سے سوال کیا گیا تھا — یعنی بنی اسرائیل نے موسیٰ سے گائے کی تفصیل پوچھتے پوچھتے معاملہ مشکل کر دیا تھا۔
۳۔ ’’وَمَن يَتَبَدَّلِ الْكُفْرَ بِالْإِيمَانِ فَقَدْ ضَلَّ سَوَاءَ السَّبِيلِ‘‘ — اور جس نے ایمان کو کفر سے بدل لیا (تو) بے شک وہ سیدھے راستے سے بھٹک گیا — یعنی ایمان کو چھوڑ کر انکار کی طرف جانا براہِ راست گمراہی ہے۔
۴۔ عملی سبق: دین کے بنیادی سوالوں پر عمل کریں؛ ضرب عمروں اور تنازعی سوالات سے گریز کریں۔"""
),
116: (
"اہل کتاب میں سے اکثر یہ پسند کرتے ہیں کہ اگر وہ تمہیں تمہارے ایمان کے بعد کافر بنا دیں — حسد کی وجہ سے ان کے نفس سے — اس کے بعد کہ حق ان کے سامنے ظاہر ہو چکا — پس (تم) معاف کرو اور درگزر کرو یہاں تک کہ اللہ اپنا حکم لے آئے — بے شک اللہ ہر چیز پر قادر ہے۔",
"""۱۔ اہل کتاب کا حسد واضح کیا جا رہا ہے: وہ چاہتے ہیں کہ مسلمان اپنے ایمان سے پھر جائیں۔
۲۔ ’’وَدَّ كَثِيرٌ مِّنْ أَهْلِ الْكِتَابِ لَوْ يَرُدُّونَكُم مِّن بَعْدِ إِيمَانِكُمْ كُفَّارًا‘‘ — اہل کتاب میں سے اکثر چاہتے ہیں کہ وہ تمہیں تمہارے ایمان کے بعد کافر بنا دیں — یعنی ایمان کی روشنی انہیں شدید پریشان کرتی ہے۔
۳۔ ’’حَسَدًا مِّنْ عِندِ أَنفُسِهِم‘‘ — اپنے نفس کے حسد کی وجہ سے — یعنی صرف خودپرستی اور رشک، نہ کوئی عقلی دلیل۔
۴۔ ’’مِّن بَعْدِ مَا تَبَيَّنَ لَهُمُ الْحَقُّ‘‘ — اس کے بعد کہ حق ان کے سامنے ظاہر ہو چکا — یعنی وہ خود بھی جانتے ہیں کہ قرآن حق ہے۔
۵۔ ’’فَاعْفُوا وَاصْفَحُوا حَتَّىٰ يَأْتِيَ اللّٰہُ بِأَمْرِهِ‘‘ — پس (تم) معاف کرو اور درگزر کرو یہاں تک کہ اللہ اپنا حکم لے آئے — یعنی صبر اور تحمل اختیار کرو، اگر تم کا بدلہ ابھی نہیں تو اللہ کا فیصلہ آئے گا۔
۶۔ ’’إِنَّ اللّٰہَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — بے شک اللہ ہر چیز پر قادر ہے — یعنی اللہ کی مشیت کے سامنے کوئی طاقت نہیں ٹکتی۔
۷۔ عملی سبق: دشمنوں کے حسد اور عناد کے مقابلے میں صبر اور درگزر سب سے بڑی طاقت ہے؛ اللہ کا حکم سب سے مضبوط فیصلہ ہے۔"""
),
117: (
"اور نماز قائم کرو اور زکوٰۃ دو — اور جو بھلائی بھی تم اپنے لیے آگے بھیجو گے اسے اللہ کے پاس پاؤ گے — بے شک اللہ دیکھتا ہے جو تم عمل کرتے ہو۔",
"""۱۔ دو اہم عبادتیں دوبارہ بیان ہوئیں: نماز اور زکوٰۃ — جو حقوق اللہ اور حقوق الناس دونوں کی ادائیگی ہیں۔
۲۔ ’’وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللّٰہِ‘‘ — اور جو بھلائی بھی تم اپنے لیے آگے بھیجو گے اسے اللہ کے پاس پاؤ گے — یعنی ہر نیکی (زکوٰۃ سمیت) اللہ کے حضور وصول ہوتی ہے۔
۳۔ ’’إِنَّ اللّٰہَ بِمَا تَعْمَلُونَ بَصِيرٌ‘‘ — بے شک اللہ دیکھتا ہے جو تم عمل کرتے ہو — یعنی تمہارا ہر عمل اللہ کی نظر میں ہے — اس لیے اخلاص شرط ہے۔
۴۔ عملی سبق: ہر نیکی کو اللہ کی طرف سے وعدۂ آخرت سمجھ کر کرو؛ ریاکاری اور دکھاوا دونوں سے بچیں۔"""
),
}
